#!/usr/bin/env bash
# Checks that the run manifest's source block changes with the adapter source and ignores generated bytecode.
set -euo pipefail

provenance="$1"
work="$(mktemp -d)"
trap 'rm -rf -- "$work"' EXIT
fail() {
  echo "FAIL: $*" >&2
  exit 1
}

repo="$work/repo"
mkdir -p "$repo/scripts" "$repo/adapters/lerobot" "$repo/src"
cp -- "$provenance" "$repo/scripts/print_source_provenance.sh"
printf '__pycache__/\n*.pyc\n' >"$repo/.gitignore"
echo 'print("served")' >"$repo/adapters/lerobot/server.py"
echo 'core' >"$repo/src/core.txt"
git -C "$repo" init -q
git -C "$repo" add -A
git -C "$repo" -c user.name=rovi -c user.email=rovi@example.invalid commit -q -m base
block() { bash "$repo/scripts/print_source_provenance.sh"; }

clean="$(block)"
grep -qx "  dirty: false" <<<"$clean" || fail "a clean checkout was reported dirty"
[[ "$(block)" == "$clean" ]] || fail "an unchanged checkout changed its source block"

echo 'print("served differently")' >"$repo/adapters/lerobot/server.py"
edited="$(block)"
grep -qx "  dirty: true" <<<"$edited" || fail "an edited adapter was not reported dirty"
echo 'print("served a third way")' >"$repo/adapters/lerobot/server.py"
[[ "$(block)" != "$edited" ]] || fail "two different adapter edits gave the same source block"
echo 'print("served differently")' >"$repo/adapters/lerobot/server.py"

echo 'helper = 1' >"$repo/adapters/lerobot/helper.py"
added="$(block)"
[[ "$added" != "$edited" ]] || fail "an untracked adapter file left the source block unchanged"

mkdir -p "$repo/adapters/lerobot/__pycache__"
echo 'bytecode' >"$repo/adapters/lerobot/__pycache__/server.cpython-312.pyc"
[[ "$(block)" == "$added" ]] || fail "generated bytecode changed the source block"
echo "source provenance checks passed"
